/**
 * Universal Image & Visual Diagram Detection Utility for Kurikulum Merdeka Assessment
 * 
 * Accurately detects, parses, and cleans any image tags or visual context cues
 * across all subjects (IPAS, Matematika, Bahasa Indonesia, Bahasa Inggris, PPKn, IPS, PJOK, Seni, etc.)
 */

export interface QuestionImageData {
  hasImage: boolean;
  imageDescription: string;
  cleanedStimulus: string;
  cleanedPertanyaan: string;
  customImageUrl?: string;
}

// Comprehensive regex matching any visual placeholder tags generated by AI models
export const UNIVERSAL_IMAGE_TAG_REGEX =
  /\[(?:KOTAK\s+)?(?:GAMBAR|DIAGRAM|ILUSTRASI|GRAFIK|BAGAN|IMAGE|SKETSA|FOTO|PETA|DENAH):\s*([^\]]+)\]/gi;

// Visual contextual phrases indicating the question relies on an illustration
const VISUAL_CONTEXT_PHRASES = [
  'perhatikan gambar',
  'berdasarkan gambar',
  'pada gambar',
  'gambar di samping',
  'gambar di bawah',
  'gambar di atas',
  'gambar berikut',
  'amati gambar',
  'cermati gambar',
  'perhatikan diagram',
  'berdasarkan diagram',
  'diagram berikut',
  'diagram di bawah',
  'perhatikan grafik',
  'berdasarkan grafik',
  'grafik berikut',
  'perhatikan bagan',
  'berdasarkan bagan',
  'bagan alur',
  'perhatikan denah',
  'berdasarkan denah',
  'perhatikan peta',
  'berdasarkan peta',
  'perhatikan ilustrasi',
  'berdasarkan ilustrasi',
  'look at the picture',
  'see the picture',
  'look at the diagram',
  'based on the picture',
  'observe the picture',
];

/**
 * Universal extractor that guarantees every image-requiring question gets
 * properly identified, cleaned, and supplied with an illustrative description.
 */
export function extractQuestionImageData(soal: {
  nomor_soal?: number;
  stimulus?: string;
  pertanyaan?: string;
  membutuhkan_gambar?: boolean;
  gambar_url?: string;
  image_url?: string;
}): QuestionImageData {
  const stimulus = soal.stimulus || '';
  const pertanyaan = soal.pertanyaan || '';
  const customUrl = soal.gambar_url || (soal as any).image_url || '';

  // 1. Search for bracketed image tags in stimulus or pertanyaan
  let extractedDescription = '';
  const stimulusMatches = Array.from(stimulus.matchAll(UNIVERSAL_IMAGE_TAG_REGEX));
  const pertanyaanMatches = Array.from(pertanyaan.matchAll(UNIVERSAL_IMAGE_TAG_REGEX));

  if (stimulusMatches.length > 0 && stimulusMatches[0][1]) {
    extractedDescription = stimulusMatches[0][1].trim();
  } else if (pertanyaanMatches.length > 0 && pertanyaanMatches[0][1]) {
    extractedDescription = pertanyaanMatches[0][1].trim();
  }

  // 2. Clean the raw tags out of the text so no ugly "[KOTAK GAMBAR: ...]" appears in the UI
  const cleanedStimulus = stimulus.replace(UNIVERSAL_IMAGE_TAG_REGEX, '').trim();
  const cleanedPertanyaan = pertanyaan.replace(UNIVERSAL_IMAGE_TAG_REGEX, '').trim();

  // 3. Check for implicit visual context phrases in the text
  const combinedTextLower = `${cleanedStimulus} ${cleanedPertanyaan}`.toLowerCase();
  const hasVisualPhrase = VISUAL_CONTEXT_PHRASES.some((phrase) =>
    combinedTextLower.includes(phrase)
  );

  // 4. Determine final hasImage flag
  const hasImage =
    Boolean(soal.membutuhkan_gambar) ||
    Boolean(extractedDescription) ||
    Boolean(customUrl) ||
    hasVisualPhrase;

  // 5. If hasImage is true but extractedDescription is empty, synthesize a smart context description
  if (hasImage && !extractedDescription) {
    // Attempt to extract the subject from phrases like "Perhatikan gambar [subjek] berikut"
    const matchSubject = combinedTextLower.match(/perhatikan gambar ([^.,;!?\n]+)/i);
    if (matchSubject && matchSubject[1]) {
      extractedDescription = matchSubject[1].trim();
    } else {
      extractedDescription = cleanedPertanyaan || cleanedStimulus || 'Bagan Ilustrasi Konseptual';
    }
  }

  return {
    hasImage,
    imageDescription: extractedDescription,
    cleanedStimulus,
    cleanedPertanyaan,
    customImageUrl: customUrl || undefined,
  };
}
